module ContestScheduler (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [1:0] Z,\n    input wire [2:0] dow_oct1_0,\n    input wire [2:0] dow_oct1_1,\n    input wire [30:0] forbidden_mask_0,\n    input wire [30:0] forbidden_mask_1,\n    output reg [4:0] day0,\n    output reg [4:0] day1,\n    output reg [16:0] total_penalty,\n    output reg done\n);\n\n    // Internal parameters\n    localparam [2:0] MAX_ALLOWED = 3'd5;\n    localparam [16:0] MAX_PENALTY = 17'h1FFFF;\n    \n    // Function to compute Thanksgiving Friday\n    function [4:0] calc_tsg_friday;\n        input [2:0] dow_oct1;\n        integer offset, first_mon, second_mon;\n        begin\n            offset = (1 - dow_oct1 + 7'd7) % 7'd7;\n            first_mon = 1 + offset;\n            second_mon = first_mon + 7'd7;\n            calc_tsg_friday = second_mon - 2;\n        end\n    endfunction\n\n    // Allowed Fridays arrays\n    reg [4:0] allowed0 [0:4];\n    reg [2:0] count0;\n    reg [4:0] allowed1 [0:4];\n    reg [2:0] count1;\n    \n    // Precompute TSG Fridays\n    wire [4:0] tsg0 = calc_tsg_friday(dow_oct1_0);\n    wire [4:0] tsg1 = calc_tsg_friday(dow_oct1_1);\n    \n    // Combinational logic for allowed days\n    integer d;\n    always @(*) begin\n        count0 = 3'd0;\n        for (d = 1; d <= 31; d = d + 1) begin\n            if (((dow_oct1_0 + (d - 1)) % 7) == 5) begin  // Is Friday?\n                if (~forbidden_mask_0[d-1] && (d != tsg0) && (count0 < MAX_ALLOWED)) begin\n                    allowed0[count0] = d;\n                    count0 = count0 + 1;\n                end\n            end\n        end\n    end\n    \n    always @(*) begin\n        count1 = 3'd0;\n        for (d = 1; d <= 31; d = d + 1) begin\n            if (((dow_oct1_1 + (d - 1)) % 7) == 5) begin  // Is Friday?\n                if (~forbidden_mask_1[d-1] && (d != tsg1) && (count1 < MAX_ALLOWED)) begin\n                    allowed1[count1] = d;\n                    count1 = count1 + 1;\n                end\n            end\n        end\n    end\n    \n    // Optimal penalty calculation\n    reg [16:0] best_pen;\n    reg [4:0] best_d0;\n    reg [4:0] best_d1;\n    integer i, j;\n    \n    always @(*) begin\n        best_pen = MAX_PENALTY;\n        best_d0 = 5'd0;\n        best_d1 = 5'd0;\n        \n        if (Z == 2'd1) begin\n            for (i = 0; i < count0; i = i + 1) begin\n                if ((allowed0[i] - 5'd12) * (allowed0[i] - 5'd12) < best_pen) begin\n                    best_pen = (allowed0[i] - 5'd12) * (allowed0[i] - 5'd12);\n                    best_d0 = allowed0[i];\n                    best_d1 = 5'd0;\n                end\n            end\n        end\n        else if (Z == 2'd2) begin\n            for (i = 0; i < count0; i = i + 1) begin\n                for (j = 0; j < count1; j = j + 1) begin\n                    if (allowed1[j] >= allowed0[i]) begin\n                        if (((allowed0[i] - 5'd12)**2 + (allowed1[j] - allowed0[i])**2) < best_pen) begin\n                            best_pen = ((allowed0[i] - 5'd12)**2) + ((allowed1[j] - allowed0[i])**2);\n                            best_d0 = allowed0[i];\n                            best_d1 = allowed1[j];\n                        end\n                    end\n                end\n            end\n        end\n    end\n    \n    // Output registers\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            day0 <= 5'd0;\n            day1 <= 5'd0;\n            total_penalty <= 17'd0;\n            done <= 1'b0;\n        end\n        else begin\n            day0 <= best_d0;\n            day1 <= best_d1;\n            total_penalty <= best_pen;\n            done <= 1'b1;\n        end\n    end\n\nendmodule